class Base {
    // Object structure begins with VPtr (pointer to VTable)
public:
    // VTable entry 0
    virtual void step1() = 0;
    // VTable entry 1
    virtual void step2();
    virtual ~Base() {}
};

class Derived : public Base {
public:
    // VPtr updated to point to Derived's VTable
    void step1() override {}
    void step2() override {}
};

// Dispatch Mechanism (Runtime Lookup):
Base* p = new Derived();

// 1. Read p's VPtr.
// 2. Index VTable (e.g., step1() is index 0).
// 3. Call function pointed to by VTable[0].
p->step1();

delete p;
